from lib import *
S = SS('g35')
steps = [
    step("go build -gcflags=-m=2 给每个函数一个“代价”,预算是 80。可以内联:add 4、abs 9、sum(含 for range 循环)16、forWithBreak(含 break)19、withClosure(返回闭包)17、withSelect(含 select)14、withSwitch 16、callsMethod 6、(*T).M 3、callsFuncValue(调用函数值)21、panics 9、usesStd 29、big 62、callsInterface(调接口方法)61、recursive(自递归)71。不能内联:withDefer(unhandled op DEFER)、withRecover(call to recover)、withGo(unhandled op GO)、caller(function too complex: cost 96 exceeds budget 80)、main(cost 310)。", t=tl(S(1)), done=lidx(S(1), 'add  ', 'abs  ', 'sum  ', 'withSelect', 'callsMethod'), mark=lidx(S(1), 'withDefer', 'withRecover', 'withGo', 'caller ', 'main '), b=bars([['add', 4, '4'], ['sum(for range)', 16, '16'], ['big', 62, '62'], ['recursive', 71, '71'], ['预算', 80, '80'], ['caller(超出)', 96, '96']], 96, done=[0, 1, 2, 3], mark=[4, 5]), kv=KV([['可以内联', '循环、break、闭包、select、switch、方法、函数值、自递归(只要代价 ≤ 80)'], ['不能内联', 'defer、recover、go 语句,以及代价超过 80 的函数'], ['代价', 'add 4、sum 16、big 62、recursive 71、caller 96、main 310']], ['不能内联'])),
    step("调用点:caller 函数体里 add、abs、callsMethod(连同 (*T).M)、sum、panics、withSwitch 都被内联进来了;但 caller 自己因为内联进来的内容太多,代价 96 超过预算 80,没法再被 main 内联;main 的代价是 310。", t=tl(S(2)), done=lidx(S(2), 'caller 函数体'), mark=lidx(S(2), 'cannot inline caller', 'cannot inline main'), kv=KV([['caller 里的调用', 'add、abs、callsMethod、(*T).M、sum、panics、withSwitch 全部内联'], ['caller 自己', '代价 96 > 80,不能被内联'], ['原因', '被内联的小函数的代价会累加进调用者']], ['原因'])),
    step("预算 80 的边界:一个函数里连续做 k 次 x += i:k = 1 代价 5、k = 10 代价 32、k = 20 代价 62;最大还能内联的 k = 26,代价正好 80;k = 27 代价 83,超过预算。每多一条简单语句约增加 3 的代价。", t=tl(S(3)), done=lidx(S(3), 'k = 1:', 'k = 10:', 'k = 20:'), mark=lidx(S(3), '最大的 k = 26'), b=bars([['k = 1', 5, '5'], ['k = 10', 32, '32'], ['k = 20', 62, '62'], ['k = 26', 80, '80'], ['k = 27', 83, '83']], 83, done=[0, 1, 2, 3], mark=[4]), kv=KV([['k = 1 / 10 / 20', '代价 5 / 32 / 62'], ['k = 26', '代价 80,仍可内联'], ['k = 27', '代价 83,超过预算 80']], ['k = 26'])),
    step("内联对运行成本的影响(7 轮取中位数):调用 addInl(i, 1) 2.33 ns/op,调用 //go:noinline 的 addNoInl 1.99 ns/op——在这个微基准里内联没有带来可见的收益(差异来自循环本身的代码,我没有深究);指针不逃逸的 newPInl(i, 1).x 2.07 ns/op、0 次分配,//go:noinline 的 newPNoInl 6.34 ns/op、1 次分配。同一份代码加 -gcflags=-l 关闭内联:addInl 1.98 ns/op;newPInl 变成 6.52 ns/op、1 次分配。内联的真正收益是让逃逸分析看到全貌。", t=tl(S(4)), done=lidx(S(4), '内联的 addInl', '内联的 newPInl'), mark=lidx(S(4), 'newPNoInl', '-gcflags=-l', 'AllocsPerRun'), b=bars([['内联 newPInl(默认)', 2.07, '2.07'], ['noinline newPNoInl', 6.34, '6.34'], ['newPInl(-l 关闭内联)', 6.52, '6.52'], ['addInl(默认)', 2.33, '2.33'], ['addNoInl', 1.99, '1.99']], 6.52, done=[0, 3, 4], mark=[1, 2]), kv=KV([['返回指针的小函数', '内联后不逃逸:2.07 ns、0 次分配;不内联:6.34 ns、1 次分配'], ['加 -gcflags=-l', 'newPInl 也变成 6.52 ns、1 次分配'], ['简单的加法', '内联与否在这个基准里没有可见差别']], ['返回指针的小函数'])),
    step("标准库函数的内联(来自编译后导出的函数体):f 里调用 strings.Index、strings.HasPrefix(里面还内联了 stringslite.HasPrefix)、bytes.Equal、utf8.RuneLen 都被内联;math.Abs 没有出现在 inlining 诊断里。", t=tl(S(5)), done=lidx(S(5), 'strings.Index', 'strings.HasPrefix', 'bytes.Equal', 'utf8.RuneLen', 'stringslite.HasPrefix'), kv=KV([['strings.Index、strings.HasPrefix', '内联'], ['bytes.Equal、utf8.RuneLen', '内联'], ['stringslite.HasPrefix', '被 strings.HasPrefix 内联进来的内部函数'], ['跨包', '标准库的小函数可以被用户代码内联']], ['跨包'])),
]
A = mkartg('g35', 35, 'Go,内联,编译器,gcflags,逃逸分析,真实验证,动画演示',
    '用 go build -gcflags=-m=2 读 Go 1.27.1 的内联诊断:预算 80,add 4、sum 16、big 62、recursive 71 可以内联,defer、recover、go 语句与代价超出的 caller(96)、main(310)不能;一连串 x += i 最多 26 条(代价 80);内联的收益在这个微基准里体现在逃逸分析上(返回指针的小函数内联后 0 次分配,关闭内联后 1 次分配);标准库的小函数可以被内联。',
    '内联是编译器最重要的优化之一,但它由一个“代价预算”决定,不是由函数行数决定。这篇用编译器自己的诊断看清:哪些写法能内联、代价怎么算、预算的边界在哪里、内联真正改变了什么——以及它没有改变什么。',
    [('预算 80', 'caller 代价 96 被拒绝,k = 26 条 x += i 代价 80 刚好通过,k = 27 代价 83 被拒绝'), ('不能内联', 'defer、recover、go 语句(unhandled op DEFER / GO、call to recover)'), ('0 次 vs 1 次', '返回指针的小函数:内联后分配 0 次,关闭内联后分配 1 次')],
    [('怎么读诊断', '<p><code>can inline f with cost N</code> 是说 f 能被内联,N 是它的代价;<code>cannot inline f: function too complex: cost 96 exceeds budget 80</code> 是代价超出;<code>unhandled op DEFER</code> 这类是遇到了编译器目前不支持内联的语句。<code>-m=2</code> 比 <code>-m</code> 多打印原因与代价。</p>'),
     ('代价是怎么累加的', '<p>每个节点(运算、语句、调用)按固定权重累加;内联进来的函数的代价也要计入调用者。所以 <code>add</code>、<code>abs</code> 这样的小函数一个个都能内联,但把它们放在同一个 <code>caller</code> 里之后,<code>caller</code> 自己就超出预算,不再能被别人内联。实验里连续的 <code>x += i</code> 每条约 3 的代价,最多 26 条。</p>'),
     ('哪些写法被拒绝', '<p>这个版本里 <code>for</code>(含 <code>break</code>)、闭包、<code>select</code>、<code>switch</code>、方法、函数值调用、自递归都能内联;<code>defer</code>、<code>recover</code>、<code>go</code> 语句不行。别把“有循环就不能内联”之类旧结论当成现状,以你所用版本的诊断为准。</p>'),
     ('内联到底改变了什么', '<p>最直观的收益是去掉调用开销,但在这个紧循环微基准里没有看到(内联的 <code>addInl</code> 反而略慢,差异我没有深究)。更实在的收益是内联之后逃逸分析能看到调用者的全貌:<code>newPInl</code> 返回的指针没有逃出调用者,于是 <code>&amp;P{}</code> 留在栈上,0 次分配;关闭内联后同一段代码就多一次分配、慢 3 倍(见上一篇逃逸分析)。</p>'),
     ('跨包内联', '<p>标准库里的小函数(<code>strings.HasPrefix</code>、<code>bytes.Equal</code>、<code>utf8.RuneLen</code> 等)也会被内联进你的代码,因为编译好的包里带着可内联函数的函数体。<code>math.Abs</code> 没有出现在诊断里,我没有查它是不是被当成内建指令处理了。</p>')],
    steps,
    [ENV_G + '。诊断来自 go build -gcflags=-m=2 的原样输出(函数代价在源码里按名字对应);预算边界用二分法反复编译;基准测试每个变体 7 轮取中位数,每个函数 //go:noinline 或不加,-l 对照另跑一遍',
     '没有验证:PGO 提高内联预算的效果(见 PGO 一篇)、编译器源码里每种节点的具体权重、-gcflags=-l=4 等历史选项、泛型函数与接口方法的去虚拟化内联、math.Abs 等内建函数的处理、amd64 上的诊断是否相同'],
    '内联')
